const runHour = $now.hour;
const isFirstRun = (runHour === 9);
const datePostedFilter = isFirstRun ? 'pastWeek' : 'past24Hours';
const maxJobsPrimary = isFirstRun ? 30 : 15;
const maxJobsSecondary = isFirstRun ? 20 : 10;
const todayDateStr = $now.toFormat('yyyy-LL-dd');
return [{ json: { isFirstRun, datePostedFilter, maxJobsPrimary, maxJobsSecondary, todayDateStr, runHour, runTimestamp: $now.toISO() } }];

const j = $json;
const title = j.title || j.jobTitle || j.position || 'Unknown Title';
const company = j.companyName || j.company || j.company_name || 'Unknown Company';
const companyLogo = j.companyLogo || j.company_logo || j.logo || '';
const location = j.location || j.jobLocation || '';
const jobUrl = j.jobUrl || j.url || j.link || j.jobLink || '';
const description = j.descriptionText || j.description || j.jobDescription || j.descriptionHtml || '';
const salaryText = j.salary || j.salaryText || j.compensation || '';
const postedDate = j.postedDate || j.datePosted || j.postedAt || '';
const jobId = j.jobId || j.id || jobUrl;

const runCtx = $('Compute Run Window').first().json;

function parseAgeMinutes(text) {
  if (!text) return null;
  const t = String(text).toLowerCase().trim();
  if (t.includes('just now') || t.includes('moment')) return 0;
  const match = t.match(/(\d+)\s*(minute|hour|day|week|month)/);
  if (!match) return null;
  const n = parseInt(match[1], 10);
  const unitMinutes = { minute: 1, hour: 60, day: 1440, week: 10080, month: 43200 };
  return n * (unitMinutes[match[2]] || 0);
}

const ageMinutes = parseAgeMinutes(postedDate);
const ageHours = ageMinutes === null ? null : ageMinutes / 60;
const postedMoment = ageMinutes === null ? null : $now.minus({ minutes: ageMinutes });
const postedDateStr = postedMoment === null ? null : postedMoment.toFormat('yyyy-LL-dd');
const isSameDay = postedDateStr !== null && postedDateStr === runCtx.todayDateStr;
const isVeryFresh = ageHours !== null && ageHours <= 1;

const passesFreshnessFilter = runCtx.isFirstRun
  ? (ageHours !== null && ageHours <= 168)
  : (ageHours !== null && ageHours <= 1 && isSameDay);

return { json: { jobId, jobUrl, title, company, companyLogo, location, description, salaryText, postedDate, ageHours, isSameDay, isVeryFresh, passesFreshnessFilter } };

const job = $('Normalize Job Fields').item.json;

// TEMPLATE: replace this with your own resume text
const resumeText = 'PASTE YOUR RESUME TEXT HERE — name, summary, skills, work history, education. This whole block is sent to the AI on every job it scores.';

// TEMPLATE: replace with your own target role titles
const roleFamilies = 'Example Role 1, Example Role 2, Example Role 3';

// TEMPLATE: adjust to your target pay range
const targetPayRange = '$60-80 USD/hour (roughly $125K-$166K/year)';

const prompt = 'You are screening a job posting for a candidate against a strict scoring rubric. Here is the candidate resume:

' + resumeText + '

Target role families (the role should match or be closely adjacent to one of these): ' + roleFamilies + '

Here is a job posting to evaluate:
Title: ' + job.title + '
Company: ' + job.company + '
Location: ' + job.location + '
Salary/Pay listed: ' + (job.salaryText || 'Not listed') + '
Description: ' + job.description + '

STEP 1 - HARD EXCLUSIONS. Set isGoodFit to false regardless of score if the role is clearly a mismatch on location or work arrangement, seniority, or work authorization, or the posting looks expired or duplicate.

STEP 2 - SCORE (0-100) using this rubric: Location and Work Arrangement (0-25), Compensation vs target ' + targetPayRange + ' (0-20), Employment Type (0-10), Resume and Role Fit (0-35, weight this heaviest), Seniority and Scope (0-10). Bonus: +5 if the industry is a strong match, +0 otherwise.

isGoodFit should be true only if not excluded AND the total score is 65 or higher.

Also write a brief neutral 1-2 sentence summary of what the role involves day to day, and list 3-6 key skills, tools, or keywords mentioned in the posting.

Respond with ONLY a single valid JSON object (standard double-quoted JSON, no markdown fences, no extra text) containing exactly these fields: isGoodFit (boolean), matchScore (number 0-105), isRemote (boolean), payAmount (string or null), payInRange (boolean or null), otherNotes (array of strings), reasoning (string), descriptionSummary (string), keySkills (array of strings).';

return { json: { requestBody: { model: 'sonar', max_tokens: 900, messages: [{ role: 'user', content: prompt }] } } };

const respObj = $json || {};
let text = '';
if (respObj.choices && Array.isArray(respObj.choices) && respObj.choices[0] && respObj.choices[0].message) {
  text = respObj.choices[0].message.content || '';
}
text = text.trim();
text = text.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '');
if (!text.startsWith('{')) {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) { text = match[0]; }
}
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { isGoodFit: false, matchScore: 0, isRemote: null, payAmount: null, payInRange: null, reasoning: 'Could not parse AI response: ' + text.slice(0, 200), descriptionSummary: '', keySkills: [], otherNotes: [] };
}
const job = $('Normalize Job Fields').item.json;
return { json: {
  jobId: job.jobId,
  jobUrl: job.jobUrl,
  title: job.title,
  company: job.company,
  companyLogo: job.companyLogo,
  location: job.location,
  salaryText: job.salaryText,
  postedDate: job.postedDate,
  ageHours: job.ageHours,
  isVeryFresh: job.isVeryFresh,
  isGoodFit: parsed.isGoodFit === true,
  matchScore: typeof parsed.matchScore === 'number' ? parsed.matchScore : 0,
  isRemote: parsed.isRemote === true,
  payAmount: parsed.payAmount || null,
  payInRange: parsed.payInRange === true,
  reasoning: parsed.reasoning || '',
  descriptionSummary: parsed.descriptionSummary || '',
  keySkills: Array.isArray(parsed.keySkills) ? parsed.keySkills : [],
  otherNotes: Array.isArray(parsed.otherNotes) ? parsed.otherNotes : []
} };

const j = $json;
const isPriority = j.isVeryFresh === true && j.matchScore >= 80;

const skills = Array.isArray(j.keySkills) ? j.keySkills : [];
const skillsHtml = skills.length > 0 ? '<ul>' + skills.map(function(s) { return '<li>' + s + '</li>'; }).join('') + '</ul>' : '<p><em>None extracted</em></p>';

const notes = Array.isArray(j.otherNotes) ? j.otherNotes : [];
const notesHtml = notes.length > 0 ? '<ul>' + notes.map(function(n) { return '<li>' + n + '</li>'; }).join('') + '</ul>' : '<p><em>None noted</em></p>';

// TEMPLATE: replace with your own resume link/title, or remove the resume line further down if you don't want one
const RESUME_URL = 'https://example.com/your-resume-link';
const RESUME_TITLE = 'Your Name — Resume';

const subjectPrefix = isPriority ? '🔥 PRIORITY MATCH: ' : 'New Job Match: ';
const subject = subjectPrefix + j.title + ' at ' + (j.company || 'Unknown Company') + ' (' + j.matchScore + '% fit)';

const html = ''
  + '<h2>' + (isPriority ? '🔥 ' : '') + j.title + '</h2>'
  + '<p><strong>' + (j.company || 'Unknown Company') + '</strong> — ' + (j.location || 'Not specified') + '</p>'
  + '<table cellpadding="4" cellspacing="0">'
  + '<tr><td><strong>Posted</strong></td><td>' + (j.postedDate || 'Unknown') + '</td></tr>'
  + '<tr><td><strong>Match Score</strong></td><td>' + j.matchScore + '/100</td></tr>'
  + '<tr><td><strong>Remote</strong></td><td>' + (j.isRemote ? 'Yes' : 'Not confirmed') + '</td></tr>'
  + '<tr><td><strong>Pay</strong></td><td>' + (j.payAmount || 'Not listed') + '</td></tr>'
  + '</table>'
  + '<p>' + (j.descriptionSummary || 'No summary available') + '</p>'
  + '<h3>Other Notes</h3>' + notesHtml
  + '<h3>Key Skills</h3>' + skillsHtml
  + '<h3>Why It Fits</h3><p>' + (j.reasoning || 'No reasoning provided') + '</p>'
  + '<p><a href="' + j.jobUrl + '">View Job Posting</a></p>'
  + '<p><a href="' + RESUME_URL + '">' + RESUME_TITLE + '</a></p>';

return { json: { subject: subject, html: html, jobId: j.jobId, jobUrl: j.jobUrl, title: j.title, company: j.company, matchScore: j.matchScore, isGoodFit: j.isGoodFit, isPriority: isPriority, descriptionSummary: j.descriptionSummary, keySkills: skills, otherNotes: notes } };
